use crate::{editor::{Action,Editor},scene::Scene};
use session_rust::Xform;
use std::rc::Rc;
fn editor()->Editor{let mut e=Editor::default();e.apply(Action::Close).unwrap();e}
fn command(e:&mut Editor,line:&str)->Result<(),String>{let action=if let Some(a)=e.tool_line(line){a.map_err(str::to_owned)?}else{let crate::commands::Command::Editor(a)=crate::commands::parse(line)? else{return Err("Editor command".into())};a};e.apply(action).map_err(|message|if message=="Shape input invalid"{e.tool_status.clone()}else{message.into()})?;Ok(())}
#[test]
fn extrude_preselected_placed_originals_builds_all_profiles_once_and_selects_new_geometry(){
    let mut e=editor();command(&mut e,"CPlane XY").unwrap();command(&mut e,"Polyline Rectangle w0,0,0 w1,2,0").unwrap();command(&mut e,"Line w3,0,0 w3,2,0").unwrap();let a=e.scene.paths()[0].id;let b=e.scene.lines()[0].id;e.scene.place_following(a,Xform::translation(10.,0.,0.)).unwrap();let original=match &e.scene.paths()[0].prepared.source{crate::chain::Source::Polyline(p)=>p.clone(),_=>panic!()};e.select_objects([a,b],false);command(&mut e,"Extrude 2").unwrap();assert_eq!(e.scene.objects().len(),2);assert!(e.scene.objects()[0].cad.as_ref().unwrap().source.is_closed(0));assert!(e.scene.objects()[1].surface.is_some());let bounds=e.scene.selected_bounds(e.scene.objects()[0].id).unwrap();assert!((bounds.min[0]-10.).abs()<1e-6&&(bounds.max[0]-11.).abs()<1e-6);assert_eq!(e.selected_objects(),e.scene.objects().iter().map(|r|r.id).collect::<Vec<_>>());assert!(matches!(&e.scene.paths()[0].prepared.source,crate::chain::Source::Polyline(p)if Rc::ptr_eq(p,&original)));command(&mut e,"Undo").unwrap();assert!(e.scene.objects().is_empty());assert_eq!(e.scene.paths().len(),1);assert_eq!(e.scene.lines().len(),1);command(&mut e,"Redo").unwrap();assert_eq!(e.scene.objects().len(),2);
}
#[test]
fn curve_picks_toggle_in_order_skip_locked_and_cancel_restores_initial_selection(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w1,0,0").unwrap();command(&mut e,"Line w2,0,0 w3,0,0").unwrap();let(a,b)=(e.scene.lines()[0].id,e.scene.lines()[1].id);e.select_objects([a],false);command(&mut e,"Extrude").unwrap();assert!(e.selected_objects().is_empty());assert!(!e.gathering_curves());command(&mut e,"Escape").unwrap();assert_eq!(e.selected_objects(),vec![a]);e.select_objects([],false);command(&mut e,"Extrude 1").unwrap();assert!(e.gathering_curves());assert!(e.apply(Action::GatherPick(None)).is_err());e.apply(Action::GatherPick(Some(b))).unwrap();e.apply(Action::GatherPick(Some(a))).unwrap();assert_eq!(e.draft.as_ref().unwrap().gather.as_ref().unwrap().progress.rows[0],vec![b.value(),a.value()]);assert_eq!(e.highlighted_objects(),vec![b,a]);e.apply(Action::GatherPick(Some(b))).unwrap();assert_eq!(e.draft.as_ref().unwrap().gather.as_ref().unwrap().progress.rows[0],vec![a.value()]);Rc::make_mut(&mut e.scene.view).locked.insert(b);assert!(e.apply(Action::GatherPick(Some(b))).is_err());command(&mut e,"").unwrap();assert_eq!(e.scene.objects().len(),1);assert!(e.scene.objects()[0].surface.is_some());
}
#[test]
fn cap_options_split_across_submissions_and_signed_distance_do_not_mutate_source(){
    let mut e=editor();command(&mut e,"CPlane XY").unwrap();command(&mut e,"Polyline Rectangle w0,0,0 w1,1,0").unwrap();let id=e.scene.paths()[0].id;let original=match &e.scene.paths()[0].prepared.source{crate::chain::Source::Polyline(p)=>p.clone(),_=>panic!()};e.select_objects([id],false);command(&mut e,"Extrude").unwrap();command(&mut e,"Cap").unwrap();assert_eq!(e.draft.as_ref().unwrap().gather.as_ref().unwrap().typed,"cap");command(&mut e,"Off").unwrap();command(&mut e,"-2").unwrap();let cad=&e.scene.objects()[0].cad.as_ref().unwrap().source;assert!(!cad.is_closed(0));assert!(matches!(&e.scene.paths()[0].prepared.source,crate::chain::Source::Polyline(p)if Rc::ptr_eq(p,&original)));let bounds=e.scene.selected_bounds(e.scene.objects()[0].id).unwrap();assert!((bounds.min[2]+2.).abs()<1e-6&&bounds.max[2].abs()<1e-6);
}
#[test]
fn bad_distance_and_revolve_axis_batches_preserve_owner_source_and_redo(){
    let mut e=editor();command(&mut e,"Line w1,0,0 w1,0,2").unwrap();command(&mut e,"Point w4,0,0").unwrap();command(&mut e,"Undo").unwrap();let id=e.scene.lines()[0].id;e.select_objects([id],false);command(&mut e,"Extrude").unwrap();let step=e.draft.as_ref().unwrap().gather.as_ref().unwrap().progress.step;assert!(command(&mut e,"0").is_err());assert!(command(&mut e,"NaN").is_err());assert_eq!(e.draft.as_ref().unwrap().gather.as_ref().unwrap().progress.step,step);assert!(e.scene.objects().is_empty());command(&mut e,"Escape").unwrap();assert_eq!(e.selected_objects(),vec![id]);command(&mut e,"Redo").unwrap();assert_eq!(e.scene.points().len(),1);e.select_objects([id],false);command(&mut e,"Nurbs Surface Revolve w0,0,0").unwrap();assert!(command(&mut e,"w0,0,0 90").is_err());let gather=e.draft.as_ref().unwrap().gather.as_ref().unwrap();assert_eq!(gather.answers.len(),1);assert_eq!(gather.progress.answered,1);command(&mut e,"w0,0,1 90").unwrap();assert!(e.draft.is_none());assert!(e.scene.objects()[0].surface.is_some());
}
#[test]
fn revolution_defaults_to_full_turn_and_preserves_exact_original_surfaces_on_save_open(){
    let mut e=editor();command(&mut e,"Line w2,0,0 w2,0,3").unwrap();let id=e.scene.lines()[0].id;e.scene.place_following(id,Xform::translation(10.,0.,0.)).unwrap();let source=e.scene.lines()[0].prepared.source.clone();e.select_objects([id],false);command(&mut e,"nurbssurface_revolve w10,0,0 w10,0,1").unwrap();let surface=e.scene.objects()[0].surface.as_ref().unwrap().source.clone();assert!(surface.is_closed(0));assert!(surface.is_rational());assert!(Rc::ptr_eq(&source,&e.scene.lines()[0].prepared.source));let _=surface.guid();let original=surface.to_proto();let guid=e.scene.objects()[0].guid.clone();let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut reopened=Scene::empty();crate::scene_document::open(&mut reopened,&bytes).unwrap();assert_eq!(reopened.objects()[0].guid,guid);assert_eq!(reopened.objects()[0].surface.as_ref().unwrap().source.to_proto(),original);command(&mut e,"Undo").unwrap();assert!(e.scene.objects().is_empty());command(&mut e,"Redo").unwrap();assert_eq!(e.scene.objects()[0].surface.as_ref().unwrap().source.to_proto(),original);
}
#[test]
fn fixed_plane_offsets_world_prefix_and_distance_preview_are_separate_from_history(){
    let mut e=editor();command(&mut e,"CPlane XZ").unwrap();command(&mut e,"Polyline Rectangle 0,0 1,2").unwrap();let id=e.scene.paths()[0].id;e.select_objects([id],false);command(&mut e,"Extrude").unwrap();e.apply(Action::ToolHover(Some([0.,-2.,0.]))).unwrap();assert!(e.scene.objects().is_empty());assert!(!e.draft.as_ref().unwrap().outlines().is_empty());assert!(e.apply(Action::ToolPoint([0.;3])).is_err());assert_eq!(e.draft.as_ref().unwrap().cursor,Some([0.,-2.,0.]));command(&mut e,"w0,-2,0").unwrap();let bounds=e.scene.selected_bounds(e.scene.objects()[0].id).unwrap();assert!((bounds.min[1]+2.).abs()<1e-6&&bounds.max[1].abs()<1e-6);command(&mut e,"Undo").unwrap();assert!(e.scene.objects().is_empty());assert_eq!(e.scene.paths().len(),1);
}
#[test]
fn stale_original_sources_are_refused_and_invalid_begin_keeps_existing_drawing(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w1,0,0").unwrap();let id=e.scene.lines()[0].id;e.select_objects([id],false);command(&mut e,"Extrude").unwrap();e.scene.place_following(id,Xform::translation(1.,0.,0.)).unwrap();assert!(command(&mut e,"2").is_err());assert!(e.scene.objects().is_empty());assert!(e.draft.as_ref().unwrap().gather.is_some());command(&mut e,"Escape").unwrap();command(&mut e,"Curve").unwrap();command(&mut e,"w0,0,0").unwrap();assert!(command(&mut e,"Extrude 0").is_err());assert_eq!(e.draft.as_ref().unwrap().tool.name(),"Curve");assert_eq!(e.draft.as_ref().unwrap().points,vec![[0.;3]]);
}
